// Generated by esquadro: do not edit. The service keys, for those who
// administer them: the service roles as the model declares them, the keys
// with their status and last use, new keys (shown once) and revoking.
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { Ban, Check, Copy, KeyRound, Plus, TriangleAlert } from "lucide-react"
import { useState } from "react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Checkbox } from "@/components/ui/checkbox"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Field, FieldError, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { cn } from "@/lib/utils"
import { isApiError } from "@api"
import { api } from "../api.ts"
import { locale } from "../config.ts"
import { seen } from "./accounts-admin.tsx"
import { ask } from "./confirm.tsx"
import { describe } from "./errors.ts"
import { capitalize, t } from "./i18n.ts"
import { PageHeader } from "./page.tsx"
import { ErrorState } from "./states.tsx"
import { toast } from "./toast.tsx"

type Status = "active" | "expired" | "revoked"

interface ServiceKey {
  id: string
  name: string
  roles: string[]
  prefix: string
  status: Status
  created_at: string
  expires_at: string | null
  last_used_at: string | null
}

interface ServiceKeysApi {
  list(): Promise<ServiceKey[]>
  create(key: { name: string; roles: string[]; days?: number }): Promise<ServiceKey & { key: string }>
  revoke(id: string): Promise<void>
  roles(): Promise<{ items: { name: string; permissions: string[]; keys: number }[]; days: number; max_days: number; choices: number[] }>
}

const keysApi = () => (api.identity as unknown as { serviceKeys: ServiceKeysApi }).serviceKeys

const STATUS: Record<Status, { dot: string; text: string }> = {
  active: { dot: "bg-emerald-500", text: "text-emerald-600 dark:text-emerald-400" },
  expired: { dot: "bg-amber-500", text: "text-amber-600 dark:text-amber-400" },
  revoked: { dot: "bg-neutral-400", text: "text-muted-foreground" },
}

const roleLabel = (r: string) => capitalize(r.replaceAll("_", " "))
const day = (at: string) => new Date(at).toLocaleDateString(locale, { day: "numeric", month: "short", year: "numeric" })

/** The service keys: their roles in cards, the keys, a new one, revoking. */
export function ServiceKeysAdmin() {
  const queryClient = useQueryClient()
  const keys = useQuery({ queryKey: ["service-keys"], queryFn: () => keysApi().list() })
  const roles = useQuery({ queryKey: ["service-keys", "roles"], queryFn: () => keysApi().roles() })
  const [creating, setCreating] = useState(false)
  const refresh = () => queryClient.invalidateQueries({ queryKey: ["service-keys"] })
  const revoke = useMutation({
    mutationFn: (k: ServiceKey) => keysApi().revoke(k.id),
    onSuccess: () => {
      toast(t("keyRevoked"))
      refresh()
    },
    onError: (e) => toast(describe(e), "error"),
  })

  return (
    <div className="flex flex-col gap-4">
      <PageHeader
        title={t("serviceKeys")}
        description={t("serviceKeysHint")}
        actions={
          <Button onClick={() => setCreating(true)} disabled={!roles.data}>
            <Plus /> {t("newKey")}
          </Button>
        }
      />
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {(roles.data?.items ?? []).map((r) => (
          <Card key={r.name} className="gap-0 py-0">
            <CardContent className="flex flex-col gap-3 p-5">
              <div className="flex items-center gap-3">
                <span className="flex size-10 items-center justify-center rounded-full bg-primary/10 text-primary">
                  <KeyRound className="size-5" />
                </span>
                <div>
                  <p className="font-bold text-foreground">{roleLabel(r.name)}</p>
                  <p className="text-xs text-muted-foreground">{t("activeKeysCount", { count: r.keys })}</p>
                </div>
              </div>
              <div className="flex flex-wrap gap-1.5">
                {r.permissions.length === 0 ? (
                  <span className="text-xs text-muted-foreground">{t("noServiceAccess")}</span>
                ) : (
                  r.permissions.map((p) => (
                    <Badge key={p} variant="secondary" className="font-mono text-[11px]">
                      {p}
                    </Badge>
                  ))
                )}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <div className="flex flex-col gap-4 rounded-xl border border-border bg-card p-5">
        {keys.isError ? (
          <ErrorState error={keys.error} onRetry={() => keys.refetch()} />
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                {[t("name"), t("roles"), t("status"), t("expires"), t("lastUsed")].map((h) => (
                  <TableHead key={h} className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">
                    {h}
                  </TableHead>
                ))}
                <TableHead className="w-0" />
              </TableRow>
            </TableHeader>
            <TableBody>
              {keys.isPending &&
                Array.from({ length: 3 }, (_, i) => (
                  <TableRow key={i}>
                    <TableCell colSpan={6}>
                      <Skeleton className="h-9 w-full" />
                    </TableCell>
                  </TableRow>
                ))}
              {keys.data?.length === 0 && (
                <TableRow>
                  <TableCell colSpan={6} className="py-12 text-center text-sm text-muted-foreground">
                    {t("noKeys")}
                  </TableCell>
                </TableRow>
              )}
              {keys.data?.map((k) => (
                <TableRow key={k.id} className={cn(k.status !== "active" && "opacity-70")}>
                  <TableCell className="py-3">
                    <p className="font-semibold text-foreground">{k.name}</p>
                    <p className="font-mono text-xs text-muted-foreground">{k.prefix}…</p>
                  </TableCell>
                  <TableCell>
                    <div className="flex flex-wrap gap-1">
                      {k.roles.map((r) => (
                        <Badge key={r} variant="secondary">
                          {roleLabel(r)}
                        </Badge>
                      ))}
                    </div>
                  </TableCell>
                  <TableCell>
                    <span className={cn("inline-flex items-center gap-2 font-semibold", STATUS[k.status].text)}>
                      <span className={cn("size-2 rounded-full", STATUS[k.status].dot)} />
                      {t(`key_${k.status}`)}
                    </span>
                  </TableCell>
                  <TableCell className="text-muted-foreground">{k.expires_at ? day(k.expires_at) : t("untilRevoked")}</TableCell>
                  <TableCell className="text-muted-foreground">{seen(k.last_used_at)}</TableCell>
                  <TableCell>
                    {k.status !== "revoked" && (
                      <Button
                        variant="ghost"
                        size="sm"
                        className="text-destructive hover:text-destructive"
                        disabled={revoke.isPending}
                        onClick={async () => {
                          if (await ask(t("revokeKeyQ", { name: k.name }), { destructive: true, description: t("revokeKeyHint"), confirm: t("revoke") })) {
                            revoke.mutate(k)
                          }
                        }}
                      >
                        <Ban /> {t("revoke")}
                      </Button>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>
      {roles.data && <NewKeyDialog open={creating} onOpenChange={setCreating} roles={roles.data} onCreated={refresh} />}
    </div>
  )
}

/** A new key: its name, roles and lifetime; then the key, this once. */
function NewKeyDialog({
  open,
  onOpenChange,
  roles,
  onCreated,
}: {
  open: boolean
  onOpenChange: (o: boolean) => void
  roles: Awaited<ReturnType<ServiceKeysApi["roles"]>>
  onCreated: () => void
}) {
  // The lifetimes offered: those within the limit, and until revoked when there is none.
  const choices = [...roles.choices.filter((d) => roles.max_days === 0 || d <= roles.max_days), ...(roles.max_days === 0 ? [0] : [])]
  const fallback = choices.includes(roles.days) ? roles.days : (choices[choices.length - 1] ?? roles.max_days)
  const [name, setName] = useState("")
  const [picked, setPicked] = useState<string[]>([])
  const [days, setDays] = useState(fallback)
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [created, setCreated] = useState<string | null>(null)
  const [copied, setCopied] = useState(false)
  const create = useMutation({
    mutationFn: () => keysApi().create({ name: name.trim(), roles: picked, days }),
    onSuccess: (k) => {
      setCreated(k.key)
      onCreated()
    },
    onError: (e) => {
      if (isApiError(e) && e.code === "name_taken") return setErrors({ name: t("keyNameTaken") })
      if (isApiError(e) && e.code === "invalid_fields" && e.fields[0]) return setErrors({ [e.fields[0].field]: describe(e) })
      toast(describe(e), "error")
    },
  })
  const lifetime = (d: number) => (d === 0 ? t("untilRevoked") : t("daysCount", { count: d }))
  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        if (o) {
          setName("")
          setPicked([])
          setDays(fallback)
          setErrors({})
          setCreated(null)
          setCopied(false)
        }
        onOpenChange(o)
      }}
    >
      <DialogContent className="sm:max-w-md">
        {created ? (
          <div className="flex flex-col gap-5">
            <DialogHeader>
              <DialogTitle>{t("keyCreated")}</DialogTitle>
              <DialogDescription>{t("keyUsage")}</DialogDescription>
            </DialogHeader>
            <div className="flex items-center gap-2 rounded-lg border border-border bg-muted p-3">
              <code className="flex-1 font-mono text-xs break-all">{created}</code>
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label={t("copy")}
                onClick={async () => {
                  await navigator.clipboard.writeText(created)
                  setCopied(true)
                }}
              >
                {copied ? <Check /> : <Copy />}
              </Button>
            </div>
            <p className="flex items-start gap-2 text-sm font-semibold text-amber-700 dark:text-amber-400">
              <TriangleAlert className="mt-0.5 size-4 shrink-0" /> {t("keyShownOnce")}
            </p>
            <code className="rounded-md bg-muted px-3 py-2 font-mono text-xs text-muted-foreground">Authorization: Bearer {created.slice(0, 9)}…</code>
            <DialogFooter>
              <Button onClick={() => onOpenChange(false)}>{t("keySaved")}</Button>
            </DialogFooter>
          </div>
        ) : (
          <form
            className="flex flex-col gap-5"
            onSubmit={(e) => {
              e.preventDefault()
              setErrors({})
              create.mutate()
            }}
          >
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2">
                <KeyRound className="size-5 text-primary" /> {t("newKey")}
              </DialogTitle>
              <DialogDescription>{t("newKeyHint")}</DialogDescription>
            </DialogHeader>
            <FieldGroup className="gap-4">
              <Field data-invalid={errors.name ? true : undefined}>
                <FieldLabel htmlFor="key-name">{t("name")}</FieldLabel>
                <Input id="key-name" required autoFocus value={name} placeholder={t("keyNamePlaceholder")} onChange={(e) => setName(e.target.value)} />
                {errors.name && <FieldError>{errors.name}</FieldError>}
              </Field>
              <Field data-invalid={errors.roles ? true : undefined}>
                <FieldLabel>{t("roles")}</FieldLabel>
                <div className="flex flex-col gap-1">
                  {roles.items.map((r) => (
                    <label key={r.name} className="flex cursor-pointer items-center justify-between gap-3 rounded-lg px-2 py-2 hover:bg-muted">
                      <span>
                        <span className="block text-sm font-semibold">{roleLabel(r.name)}</span>
                        <span className="block text-xs text-muted-foreground">{r.permissions.join(" · ") || t("noServiceAccess")}</span>
                      </span>
                      <Checkbox
                        checked={picked.includes(r.name)}
                        onCheckedChange={(c) => setPicked(c ? [...picked, r.name] : picked.filter((x) => x !== r.name))}
                      />
                    </label>
                  ))}
                </div>
                {errors.roles && <FieldError>{errors.roles}</FieldError>}
              </Field>
              <Field data-invalid={errors.days ? true : undefined}>
                <FieldLabel htmlFor="key-days">{t("expires")}</FieldLabel>
                <Select value={String(days)} onValueChange={(v) => setDays(Number(v))}>
                  <SelectTrigger id="key-days">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {choices.map((d) => (
                      <SelectItem key={d} value={String(d)}>
                        {lifetime(d)}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {errors.days && <FieldError>{errors.days}</FieldError>}
              </Field>
            </FieldGroup>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
                {t("cancel")}
              </Button>
              <Button type="submit" disabled={create.isPending || !name.trim() || picked.length === 0}>
                <KeyRound /> {t("createKey")}
              </Button>
            </DialogFooter>
          </form>
        )}
      </DialogContent>
    </Dialog>
  )
}
